kday() == 2:  # Wednesday is 2\n        wednesdays.append(date)\n\nprint('Thursdays in Jan 1939:', thursdays)\nprint('Wednesdays in Jan 1939:', wednesdays)\nprint('Third Thursday:', thursdays[2] if len(thursdays) > 2 else None)\nprint('Fourth Wednesday:', wednesdays[3] if len(wednesdays) > 3 else None)\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
