:\n                latam = cells[9]\n                results[(name.replace(':', '').strip(), date)] = latam\n                print(f'{name} - {date}: Latin America = {latam}')\n\nprint('\\\\n--- All Results ---')\nprint(results)\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
